class OtaStateMachine { OtaState _state=OtaState.idle; OtaState get state=>_state; static const transitions=<OtaState,Set<OtaState>>{OtaState.idle:{OtaState.preparing},OtaState.preparing:{OtaState.ready,OtaState.failed,OtaState.cancelled},OtaState.ready:{OtaState.beginning,OtaState.cancelling,OtaState.failed},OtaState.beginning:{OtaState.receiving,OtaState.failed,OtaState.cancelled},OtaState.receiving:{OtaState.verifying,OtaState.cancelling,OtaState.failed},OtaState.verifying:{OtaState.verified,OtaState.failed},OtaState.verified:{OtaState.committing,OtaState.failed},OtaState.committing:{OtaState.rebootPending,OtaState.failed},OtaState.rebootPending:{OtaState.reconnecting,OtaState.failed},OtaState.reconnecting:{OtaState.versionChecking,OtaState.failed},OtaState.versionChecking:{OtaState.success,OtaState.failed},OtaState.cancelling:{OtaState.cancelled,OtaState.failed},OtaState.success:{OtaState.idle},OtaState.failed:{OtaState.idle},OtaState.cancelled:{OtaState.idle}}; void transitionTo(OtaState next){if(!(transitions[_state]??const <OtaState>{}).contains(next))throw StateError('Illegal OTA transition: ${_state.name} -> ${next.name}');_state=next;} }
